#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum TopLevelDeclaration {
    FunctionDef(FunctionDef),
    ClassDef(ClassDef),
    EnumDef(EnumDef),
    InterfaceDef(InterfaceDef),
    ImplementsFor(ImplementsFor),
    ClientDef(ClientDef),
    ClientValueDef(ClientValueDef),
    TestDef(TestDef),
    TestExprDef(TestExprDef),
    TestsetDef(TestsetDef),
    HeaderComment(HeaderComment),
    GeneratorDef(GeneratorDef),
    RetryPolicyDef(RetryPolicyDef),
    TemplateStringDef(TemplateStringDef),
    TypeAliasDef(TypeAliasDef),
}

impl AstNode for TopLevelDeclaration {
    type Language = BamlLanguage;
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            SyntaxKind::FUNCTION_DEF
                | SyntaxKind::CLASS_DEF
                | SyntaxKind::ENUM_DEF
                | SyntaxKind::INTERFACE_DEF
                | SyntaxKind::IMPLEMENTS_FOR
                | SyntaxKind::CLIENT_DEF
                | SyntaxKind::CLIENT_VALUE_DEF
                | SyntaxKind::TEST_DEF
                | SyntaxKind::TEST_EXPR_DEF
                | SyntaxKind::TESTSET_DEF
                | SyntaxKind::HEADER_COMMENT
                | SyntaxKind::GENERATOR_DEF
                | SyntaxKind::RETRY_POLICY_DEF
                | SyntaxKind::TEMPLATE_STRING_DEF
                | SyntaxKind::TYPE_ALIAS_DEF
        )
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        match syntax.kind() {
            SyntaxKind::FUNCTION_DEF => Some(Self::FunctionDef(FunctionDef { syntax })),
            SyntaxKind::CLASS_DEF => Some(Self::ClassDef(ClassDef { syntax })),
            SyntaxKind::ENUM_DEF => Some(Self::EnumDef(EnumDef { syntax })),
            SyntaxKind::INTERFACE_DEF => Some(Self::InterfaceDef(InterfaceDef { syntax })),
            SyntaxKind::IMPLEMENTS_FOR => Some(Self::ImplementsFor(ImplementsFor { syntax })),
            SyntaxKind::CLIENT_DEF => Some(Self::ClientDef(ClientDef { syntax })),
            SyntaxKind::CLIENT_VALUE_DEF => Some(Self::ClientValueDef(ClientValueDef { syntax })),
            SyntaxKind::TEST_DEF => Some(Self::TestDef(TestDef { syntax })),
            SyntaxKind::TEST_EXPR_DEF => Some(Self::TestExprDef(TestExprDef { syntax })),
            SyntaxKind::TESTSET_DEF => Some(Self::TestsetDef(TestsetDef { syntax })),
            SyntaxKind::HEADER_COMMENT => Some(Self::HeaderComment(HeaderComment { syntax })),
            SyntaxKind::GENERATOR_DEF => Some(Self::GeneratorDef(GeneratorDef { syntax })),
            SyntaxKind::RETRY_POLICY_DEF => Some(Self::RetryPolicyDef(RetryPolicyDef { syntax })),
            SyntaxKind::TEMPLATE_STRING_DEF => {
                Some(Self::TemplateStringDef(TemplateStringDef { syntax }))
            }
            SyntaxKind::TYPE_ALIAS_DEF => Some(Self::TypeAliasDef(TypeAliasDef { syntax })),
            _ => None,
        }
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::FunctionDef(node) => node.syntax(),
            Self::ClassDef(node) => node.syntax(),
            Self::EnumDef(node) => node.syntax(),
            Self::InterfaceDef(node) => node.syntax(),
            Self::ImplementsFor(node) => node.syntax(),
            Self::ClientDef(node) => node.syntax(),
            Self::ClientValueDef(node) => node.syntax(),
            Self::TestDef(node) => node.syntax(),
            Self::TestExprDef(node) => node.syntax(),
            Self::TestsetDef(node) => node.syntax(),
            Self::HeaderComment(node) => node.syntax(),
            Self::GeneratorDef(node) => node.syntax(),
            Self::RetryPolicyDef(node) => node.syntax(),
            Self::TemplateStringDef(node) => node.syntax(),
            Self::TypeAliasDef(node) => node.syntax(),
        }
    }
}

impl From<FunctionDef> for TopLevelDeclaration {
    fn from(node: FunctionDef) -> Self {
        Self::FunctionDef(node)
    }
}

impl From<ClassDef> for TopLevelDeclaration {
    fn from(node: ClassDef) -> Self {
        Self::ClassDef(node)
    }
}

impl From<EnumDef> for TopLevelDeclaration {
    fn from(node: EnumDef) -> Self {
        Self::EnumDef(node)
    }
}

impl From<InterfaceDef> for TopLevelDeclaration {
    fn from(node: InterfaceDef) -> Self {
        Self::InterfaceDef(node)
    }
}

impl From<ImplementsFor> for TopLevelDeclaration {
    fn from(node: ImplementsFor) -> Self {
        Self::ImplementsFor(node)
    }
}

impl From<ClientDef> for TopLevelDeclaration {
    fn from(node: ClientDef) -> Self {
        Self::ClientDef(node)
    }
}

impl From<ClientValueDef> for TopLevelDeclaration {
    fn from(node: ClientValueDef) -> Self {
        Self::ClientValueDef(node)
    }
}

impl From<TestDef> for TopLevelDeclaration {
    fn from(node: TestDef) -> Self {
        Self::TestDef(node)
    }
}

impl From<TestExprDef> for TopLevelDeclaration {
    fn from(node: TestExprDef) -> Self {
        Self::TestExprDef(node)
    }
}

impl From<TestsetDef> for TopLevelDeclaration {
    fn from(node: TestsetDef) -> Self {
        Self::TestsetDef(node)
    }
}

impl From<HeaderComment> for TopLevelDeclaration {
    fn from(node: HeaderComment) -> Self {
        Self::HeaderComment(node)
    }
}

impl From<GeneratorDef> for TopLevelDeclaration {
    fn from(node: GeneratorDef) -> Self {
        Self::GeneratorDef(node)
    }
}

impl From<RetryPolicyDef> for TopLevelDeclaration {
    fn from(node: RetryPolicyDef) -> Self {
        Self::RetryPolicyDef(node)
    }
}

impl From<TemplateStringDef> for TopLevelDeclaration {
    fn from(node: TemplateStringDef) -> Self {
        Self::TemplateStringDef(node)
    }
}

impl From<TypeAliasDef> for TopLevelDeclaration {
    fn from(node: TypeAliasDef) -> Self {
        Self::TypeAliasDef(node)
    }
}

