#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum PatternKind {
    ChainPattern(ChainPattern),
    UnionPattern(UnionPattern),
    BindingPattern(BindingPattern),
    DestructurePattern(DestructurePattern),
    ArrayPattern(ArrayPattern),
    TypePattern(TypePattern),
    UnreflectPattern(UnreflectPattern),
    ParenPattern(ParenPattern),
    WildcardPattern(WildcardPattern),
}

impl AstNode for PatternKind {
    type Language = BamlLanguage;
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            SyntaxKind::CHAIN_PATTERN
                | SyntaxKind::UNION_PATTERN
                | SyntaxKind::BINDING_PATTERN
                | SyntaxKind::DESTRUCTURE_PATTERN
                | SyntaxKind::ARRAY_PATTERN
                | SyntaxKind::TYPE_PATTERN
                | SyntaxKind::UNREFLECT_PATTERN
                | SyntaxKind::PAREN_PATTERN
                | SyntaxKind::WILDCARD_PATTERN
        )
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        match syntax.kind() {
            SyntaxKind::CHAIN_PATTERN => Some(Self::ChainPattern(ChainPattern { syntax })),
            SyntaxKind::UNION_PATTERN => Some(Self::UnionPattern(UnionPattern { syntax })),
            SyntaxKind::BINDING_PATTERN => Some(Self::BindingPattern(BindingPattern { syntax })),
            SyntaxKind::DESTRUCTURE_PATTERN => {
                Some(Self::DestructurePattern(DestructurePattern { syntax }))
            }
            SyntaxKind::ARRAY_PATTERN => Some(Self::ArrayPattern(ArrayPattern { syntax })),
            SyntaxKind::TYPE_PATTERN => Some(Self::TypePattern(TypePattern { syntax })),
            SyntaxKind::UNREFLECT_PATTERN => {
                Some(Self::UnreflectPattern(UnreflectPattern { syntax }))
            }
            SyntaxKind::PAREN_PATTERN => Some(Self::ParenPattern(ParenPattern { syntax })),
            SyntaxKind::WILDCARD_PATTERN => Some(Self::WildcardPattern(WildcardPattern { syntax })),
            _ => None,
        }
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::ChainPattern(node) => node.syntax(),
            Self::UnionPattern(node) => node.syntax(),
            Self::BindingPattern(node) => node.syntax(),
            Self::DestructurePattern(node) => node.syntax(),
            Self::ArrayPattern(node) => node.syntax(),
            Self::TypePattern(node) => node.syntax(),
            Self::UnreflectPattern(node) => node.syntax(),
            Self::ParenPattern(node) => node.syntax(),
            Self::WildcardPattern(node) => node.syntax(),
        }
    }
}

impl From<ChainPattern> for PatternKind {
    fn from(node: ChainPattern) -> Self {
        Self::ChainPattern(node)
    }
}

impl From<UnionPattern> for PatternKind {
    fn from(node: UnionPattern) -> Self {
        Self::UnionPattern(node)
    }
}

impl From<BindingPattern> for PatternKind {
    fn from(node: BindingPattern) -> Self {
        Self::BindingPattern(node)
    }
}

impl From<DestructurePattern> for PatternKind {
    fn from(node: DestructurePattern) -> Self {
        Self::DestructurePattern(node)
    }
}

impl From<ArrayPattern> for PatternKind {
    fn from(node: ArrayPattern) -> Self {
        Self::ArrayPattern(node)
    }
}

impl From<TypePattern> for PatternKind {
    fn from(node: TypePattern) -> Self {
        Self::TypePattern(node)
    }
}

impl From<UnreflectPattern> for PatternKind {
    fn from(node: UnreflectPattern) -> Self {
        Self::UnreflectPattern(node)
    }
}

impl From<ParenPattern> for PatternKind {
    fn from(node: ParenPattern) -> Self {
        Self::ParenPattern(node)
    }
}

impl From<WildcardPattern> for PatternKind {
    fn from(node: WildcardPattern) -> Self {
        Self::WildcardPattern(node)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum BacktickSegmentNode {
    BacktickText(BacktickText),
    BacktickInterpolation(BacktickInterpolation),
    BacktickForOpen(BacktickForOpen),
    BacktickEndfor(BacktickEndfor),
    BacktickIfOpen(BacktickIfOpen),
    BacktickElseIf(BacktickElseIf),
    BacktickElse(BacktickElse),
    BacktickEndif(BacktickEndif),
}

impl AstNode for BacktickSegmentNode {
    type Language = BamlLanguage;
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            SyntaxKind::BACKTICK_TEXT
                | SyntaxKind::BACKTICK_INTERPOLATION
                | SyntaxKind::BACKTICK_FOR_OPEN
                | SyntaxKind::BACKTICK_ENDFOR
                | SyntaxKind::BACKTICK_IF_OPEN
                | SyntaxKind::BACKTICK_ELSE_IF
                | SyntaxKind::BACKTICK_ELSE
                | SyntaxKind::BACKTICK_ENDIF
        )
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        match syntax.kind() {
            SyntaxKind::BACKTICK_TEXT => Some(Self::BacktickText(BacktickText { syntax })),
            SyntaxKind::BACKTICK_INTERPOLATION => {
                Some(Self::BacktickInterpolation(BacktickInterpolation {
                    syntax,
                }))
            }
            SyntaxKind::BACKTICK_FOR_OPEN => {
                Some(Self::BacktickForOpen(BacktickForOpen { syntax }))
            }
            SyntaxKind::BACKTICK_ENDFOR => Some(Self::BacktickEndfor(BacktickEndfor { syntax })),
            SyntaxKind::BACKTICK_IF_OPEN => Some(Self::BacktickIfOpen(BacktickIfOpen { syntax })),
            SyntaxKind::BACKTICK_ELSE_IF => Some(Self::BacktickElseIf(BacktickElseIf { syntax })),
            SyntaxKind::BACKTICK_ELSE => Some(Self::BacktickElse(BacktickElse { syntax })),
            SyntaxKind::BACKTICK_ENDIF => Some(Self::BacktickEndif(BacktickEndif { syntax })),
            _ => None,
        }
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::BacktickText(node) => node.syntax(),
            Self::BacktickInterpolation(node) => node.syntax(),
            Self::BacktickForOpen(node) => node.syntax(),
            Self::BacktickEndfor(node) => node.syntax(),
            Self::BacktickIfOpen(node) => node.syntax(),
            Self::BacktickElseIf(node) => node.syntax(),
            Self::BacktickElse(node) => node.syntax(),
            Self::BacktickEndif(node) => node.syntax(),
        }
    }
}

